package com.domesticservice.booking.service;
import com.domesticservice.booking.repository.support.NativeQueryExecutor;import java.util.*;import java.sql.Timestamp;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import org.springframework.beans.factory.ObjectProvider;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.web.client.RestClient;
@Service public class ForgottenJobService {
 private final NativeQueryExecutor db;private final TransactionTemplate tx;private final ObjectProvider<BookingWorkflowService> flow;private final RestClient finance,catalog;private final String secret;
 public ForgottenJobService(NativeQueryExecutor db,PlatformTransactionManager manager,ObjectProvider<BookingWorkflowService>flow,@Value("${clients.finance.base-url}")String f,@Value("${clients.catalog.base-url}")String c,@Value("${INTERNAL_SERVICE_TOKEN:}")String secret){this.db=db;tx=new TransactionTemplate(manager);this.flow=flow;this.secret=secret;var factory=new org.springframework.http.client.JdkClientHttpRequestFactory(java.net.http.HttpClient.newBuilder().connectTimeout(java.time.Duration.ofSeconds(3)).build());factory.setReadTimeout(java.time.Duration.ofSeconds(8));finance=RestClient.builder().baseUrl(f).requestFactory(factory).build();catalog=RestClient.builder().baseUrl(c).requestFactory(factory).build();}
 public void record(long booking,long assignment,long staff,String status,String source,String note){db.update("INSERT INTO staff_execution_events(booking_id,assignment_id,staff_id,status,source,note) VALUES (?,?,?,?,?,?) ON CONFLICT DO NOTHING",booking,assignment,staff,status,source,note);}
 public void checkDeparture(Map<String,Object>b){if(secret.isBlank())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"Chưa cấu hình kiểm tra thời gian nhận ca.");Map p;try{p=finance.get().uri("/api/v1/finance/internal/discipline/policy").header("X-Service-Key",secret).retrieve().body(Map.class);}catch(RuntimeException ex){throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"Chưa kiểm tra được thời hạn di chuyển. Vui lòng thử lại.",ex);}if(p==null)throw new IllegalStateException("Missing policy");if(Boolean.TRUE.equals(p.get("no_show_enabled"))){var start=((Timestamp)b.get("starts_at")).toInstant();if(!start.isBefore(java.time.Instant.parse(p.get("effective_from").toString()))&&start.plusSeconds(((Number)p.get("grace_minutes")).longValue()*60).isBefore(java.time.Instant.now()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.CONFLICT,"Đã quá thời hạn bắt đầu di chuyển. Hệ thống đang xử lý ca quên đơn; liên hệ admin nếu cần đối chiếu.");}}
 @Scheduled(fixedDelay=10000,initialDelay=25000) public void scan(){if(secret.isBlank())return;try{var policy=finance.get().uri("/api/v1/finance/internal/discipline/policy").header("X-Service-Key",secret).retrieve().body(Map.class);if(policy!=null&&Boolean.TRUE.equals(policy.get("no_show_enabled"))){int grace=((Number)policy.get("grace_minutes")).intValue();var effective=java.time.Instant.parse(policy.get("effective_from").toString());for(long id:db.queryForList("SELECT DISTINCT b.id FROM bookings b JOIN booking_assignments a ON a.booking_id=b.id WHERE b.status IN ('CONFIRMED','ACCEPTED','STAFF_ASSIGNED') AND b.started_at IS NULL AND b.starts_at>=? AND b.starts_at+make_interval(mins=>?)<now() AND a.status='ACCEPTED' AND a.execution_status='ACCEPTED' ORDER BY b.id LIMIT 50",Long.class,Timestamp.from(effective),grace))tx.executeWithoutResult(s->cancel(id,grace,effective));}}catch(RuntimeException ex){org.slf4j.LoggerFactory.getLogger(getClass()).warn("Cannot scan forgotten jobs: {}",ex.getMessage());}deliver();}
 private void cancel(long id,int grace,java.time.Instant effective){var b=db.queryForMap("SELECT * FROM bookings WHERE id=? FOR UPDATE",id);if(!List.of("CONFIRMED","ACCEPTED","STAFF_ASSIGNED").contains(b.get("status"))||b.get("started_at")!=null||((Timestamp)b.get("starts_at")).toInstant().isBefore(effective)||!((Timestamp)b.get("starts_at")).toInstant().plusSeconds(grace*60L).isBefore(java.time.Instant.now()))return;var missed=db.queryForList("SELECT * FROM booking_assignments WHERE booking_id=? AND status='ACCEPTED' AND execution_status='ACCEPTED' ORDER BY staff_id FOR UPDATE",id);if(missed.isEmpty())return;
  String reason="Nhân viên quên đơn: quá giờ bắt đầu chưa di chuyển. Hệ thống đang xử lý hoàn tiền đã thanh toán vào ví khách hàng và cấp ưu đãi 5%.";
  for(var a:missed){String evidence="startsAt="+b.get("starts_at")+"; detectedAt="+java.time.Instant.now()+"; graceMinutes="+grace+"; assignment="+a.get("id")+"; executionStatus=ACCEPTED";record(id,((Number)a.get("id")).longValue(),((Number)a.get("staff_id")).longValue(),"NO_SHOW","SYSTEM",evidence);db.update("INSERT INTO forgotten_job_remediations(booking_id,assignment_id,staff_id,customer_id,evidence) VALUES (?,?,?,?,?) ON CONFLICT DO NOTHING",id,a.get("id"),a.get("staff_id"),b.get("customer_id"),evidence);db.insert("INSERT INTO booking_incidents(booking_id,reporter_id,reporter_role,reason,status,reported_staff_id) VALUES (?,?,'SYSTEM',?,'OPEN',?)",id,a.get("staff_id"),reason,a.get("staff_id"));}
  db.update("UPDATE bookings SET cancel_reason=?,cancelled_at=now(),cancelled_by_type='SYSTEM',staff_wait_state=CASE WHEN staff_wait_state IS NULL THEN NULL ELSE 'CLOSED' END,finance_sync_required=true WHERE id=?",reason,id);
  db.update("UPDATE booking_assignments SET status='CANCELLED',execution_status='CANCELLED',cancellation_reason=? WHERE booking_id=? AND status IN ('ASSIGNED','ACCEPTED')",reason,id);db.update("UPDATE staff_reservations SET status='CANCELLED' WHERE booking_id=? AND status IN ('HELD','CONFIRMED')",id);db.update("UPDATE conversations SET status='CLOSED',closed_at=now() WHERE booking_id=?",id);flow.getObject().transition(b,"CANCELLED",0,"SYSTEM",reason);
 }
 @SuppressWarnings("unchecked") public void deliver(){for(var r:db.queryForList("SELECT * FROM forgotten_job_remediations WHERE NOT finance_synced OR NOT voucher_synced OR NOT refund_synced ORDER BY checked_at,id LIMIT 30")){long id=((Number)r.get("id")).longValue();try{if(!Boolean.TRUE.equals(r.get("finance_synced"))){var receipt=finance.post().uri("/api/v1/finance/internal/discipline/no-show").header("X-Service-Key",secret).body(Map.of("bookingId",r.get("booking_id"),"assignmentId",r.get("assignment_id"),"staffId",r.get("staff_id"),"evidence",r.get("evidence"))).retrieve().body(Map.class);if(receipt==null||receipt.get("id")==null)throw new IllegalStateException("Missing finance receipt");tx.executeWithoutResult(s->db.update("UPDATE forgotten_job_remediations SET finance_synced=true WHERE id=?",id));}if(!Boolean.TRUE.equals(r.get("voucher_synced"))){var receipt=catalog.post().uri("/api/v1/catalog/internal/recovery-vouchers").header("X-Service-Key",secret).body(Map.of("bookingId",r.get("booking_id"),"customerId",r.get("customer_id"))).retrieve().body(Map.class);if(receipt==null||receipt.get("promotion_code")==null)throw new IllegalStateException("Missing voucher receipt");tx.executeWithoutResult(s->db.update("UPDATE forgotten_job_remediations SET voucher_synced=true,voucher_code=? WHERE id=?",receipt.get("promotion_code"),id));}if(!Boolean.TRUE.equals(r.get("refund_synced"))){var receipt=finance.post().uri("/api/v1/finance/internal/discipline/refund").header("X-Service-Key",secret).body(Map.of("bookingId",r.get("booking_id"),"customerId",r.get("customer_id"))).retrieve().body(Map.class);if(receipt==null||!"RECONCILED".equals(receipt.get("status"))||!(receipt.get("refundedAmount") instanceof Number))throw new IllegalStateException("Missing refund receipt");tx.executeWithoutResult(s->db.update("UPDATE forgotten_job_remediations SET refund_synced=true,refund_amount=? WHERE id=?",receipt.get("refundedAmount"),id));}tx.executeWithoutResult(s->db.update("UPDATE forgotten_job_remediations SET last_error=NULL,checked_at=now() WHERE id=?",id));}catch(RuntimeException ex){String error=Objects.toString(ex.getMessage(),"Unavailable");tx.executeWithoutResult(s->db.update("UPDATE forgotten_job_remediations SET last_error=?,checked_at=now() WHERE id=?",error.substring(0,Math.min(2000,error.length())),id));}}}
}
